---点击关卡
---@param stageData table 关卡数据
function XUiLuckyTenant2Main:OnClickStage(stageData)
    if not stageData then
        return
    end

    if not stageData.IsCanChallenge then
        if not stageData.IsPreStagePass then
            XUiManager.TipText("LuckyTenant2PreStageNotPass")
        elseif not stageData.IsOnTime then
            XUiManager.TipText("ActivityNotInTime")
        end
        return
    end

    if stageData.IsOtherStagePlaying then
        XUiManager.TipText("LuckyTenant2OtherStagePlaying")
        return
    end

    -- 如果正在游玩当前关卡，需要获取恢复数据后再打开游戏界面
    if stageData.IsPlaying then
        -- 请求服务器获取恢复数据
        XMVCA.XLuckyTenant2:RequestStart(stageData.Id, function(playingStage)
            -- 服务器返回成功后打开游戏界面
            -- playingStage 包含恢复游戏所需的 record 数据
            local seed = XTime.GetServerNowTimestamp()
            local isFirstTimeEntering = false -- 继续游戏，不是首次进入
            XLuaUiManager.Open("UiLuckyTenant2Game", stageData.Id, seed, isFirstTimeEntering, playingStage)
        end)
        return
    end

    -- 否则打开关卡详情
    XLuaUiManager.Open("UiLuckyTenant2PopupStageDetail", stageData.Id)
end

